        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=buku+teks"
      ]
    },
    {
      "subject": "Indonesian answer: buku pelajaran",
      "conclusion": "Valid and natural Indonesian for “textbook,” especially in an educational context.",
      "material_risk": false,
      "evidence_refs": [
        "https://buku.kemendikdasmen.go.id/",
        "https://freedict.com/translate/english-indonesian/textbook"
      ]
    },
    {
      "subject": "Malaysian answer: buku teks",
      "conclusion": "Valid and standard Malaysian Malay term meaning a textbook used for a particular subject.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=buku+teks"
      ]
    },
    {
